import{G as e,W as t,n,rt as r}from"./chunks/framework.CzKPlK1V.js";var i=JSON.parse(`{"title":"Quantity","description":"","frontmatter":{},"headers":[],"relativePath":"03-developer/models/quantity.md","filePath":"03-developer/models/quantity.md"}`),a={name:`03-developer/models/quantity.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="quantity" tabindex="-1">Quantity <a class="header-anchor" href="#quantity" aria-label="Permalink to “Quantity”">​</a></h1><p>The <code>Quantity</code> model stores the inventory and price for each combination of a product&#39;s props. A product can have multiple <code>Quantity</code> records, each representing a sellable variant of the same product.</p><p>For example, different combinations of capacity, color, and SIM type can be recorded as separate records for a product such as an iPhone. Each combination can have its own inventory and price.</p><h2 id="quantities-table" tabindex="-1"><code>quantities</code> table <a class="header-anchor" href="#quantities-table" aria-label="Permalink to “quantities table”">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>BIGINT UNSIGNED</td><td>Inventory record ID</td></tr><tr><td><code>product_id</code></td><td>BIGINT UNSIGNED</td><td>ID of the associated product; foreign key to <code>products.id</code></td></tr><tr><td><code>count</code></td><td>INT UNSIGNED, default 0</td><td>Number of units available for this product combination</td></tr><tr><td><code>price</code></td><td>DECIMAL(20,2), default 0</td><td>Price of this product combination</td></tr><tr><td><code>image</code></td><td>BIGINT UNSIGNED, nullable</td><td>Index of the product image used to display the image associated with this combination</td></tr><tr><td><code>data</code></td><td>LONGTEXT, nullable</td><td>Information about the selected props for this combination, stored as JSON</td></tr><tr><td><code>deleted_at</code></td><td>TIMESTAMP, nullable</td><td>Time when the record was soft-deleted</td></tr><tr><td><code>created_at</code></td><td>TIMESTAMP, nullable</td><td>Creation time</td></tr><tr><td><code>updated_at</code></td><td>TIMESTAMP, nullable</td><td>Last update time</td></tr></tbody></table><p>Physically deleting a product also deletes its associated <code>quantities</code> records, as specified by the foreign key (<code>ON DELETE CASCADE</code>).</p><h2 id="relationship-with-the-product" tabindex="-1">Relationship with the product <a class="header-anchor" href="#relationship-with-the-product" aria-label="Permalink to “Relationship with the product”">​</a></h2><p>The <code>product()</code> method defines a <code>belongsTo</code> relationship with the <code>Product</code> model and returns the product that owns this record.</p><h2 id="prop-information-data" tabindex="-1">Prop information (<code>data</code>) <a class="header-anchor" href="#prop-information-data" aria-label="Permalink to “Prop information (data)”">​</a></h2><p>The <code>data</code> field stores the specifications for a product combination as JSON. The JSON keys are the technical prop names (<code>Prop.name</code>), and their values specify the selected value for each prop.</p><p>For example, a record can store props such as color, storage capacity, and SIM type. This information is associated with the props defined for the product&#39;s primary category.</p><h3 id="getmetaattribute" tabindex="-1"><code>getMetaAttribute()</code> <a class="header-anchor" href="#getmetaattribute" aria-label="Permalink to “getMetaAttribute()”">​</a></h3><p>This accessor converts the value of <code>data</code> into structured information ready for display.</p><p>How it works:</p><ol><li>Converts the JSON stored in <code>data</code> to an array. If the result is <code>null</code>, it returns an empty array.</li><li>Retrieves the props associated with the product&#39;s primary category based on the names present in the JSON.</li><li>Adds the following information for each prop to the output: <ul><li><code>label</code>: Prop title</li><li><code>human_value</code>: Display-ready value</li><li><code>type</code>: Prop type</li><li><code>value</code>: Original stored value</li></ul></li><li>Generates the display value according to the prop type: <ul><li><code>color</code>: HTML color swatch</li><li><code>checkbox</code>: Check or cross icon</li><li><code>select</code> and <code>singlemulti</code>: Converts the stored value to the option title using <code>Prop.datas</code></li><li>Other types: Displays a text or array value; an empty value is replaced with <code>-</code>.</li></ul></li><li>Appends the prop&#39;s <code>unit</code> to <code>human_value</code>.</li></ol><p>The final output is an array of props keyed by each prop&#39;s technical name.</p><h2 id="use-in-the-store" tabindex="-1">Use in the store <a class="header-anchor" href="#use-in-the-store" aria-label="Permalink to “Use in the store”">​</a></h2><p>Together, <code>Quantity</code>, <code>Product</code>, and <code>Prop</code> have three distinct responsibilities:</p><ul><li><code>Product</code>: General and basic product information.</li><li><code>Prop</code>: Defines props, input types, options, and display rules.</li><li><code>Quantity</code>: Records a specific combination of prop values along with the price and inventory for that combination.</li></ul><p>This separation makes it possible to manage multiple sellable variants of a product without creating a separate product record for each variant.</p>`,20)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};